script:
//ISS-2025-00569
frappe.ui.form.on('Issue', {
    refresh: function(frm) {
        if (!frm.doc.project) return; // Если проект не выбран, выходим
        
        // Просто выходим, если проект PROJ-0028 (фильтр не применяется) ISS-2025-01765
        //if (frm.doc.project === 'S-DI-ERPN2') return; 
        
        // Получаем данные проекта
        frappe.call({
            method: 'frappe.client.get',
            args: {
                doctype: 'Project',
                name: frm.doc.project
            },
            callback: function(r) {
                if (r.message && r.message.custom_ts_details) {
                    // Собираем уникальные роли из pt_role
                    let roles = [];
                    r.message.custom_ts_details.forEach(row => {
                        if (row.pt_role && !roles.includes(row.pt_role)) {
                            roles.push(row.pt_role);
                        }
                    });
                    
                    // Устанавливаем фильтр для поля project_role
                    frm.set_query("project_role", "estimations", function() {
                        return {
                            filters: {
                                name: ["in", roles]
                            }
                        };
                    });
                }
            }
        });
    },
    
});
